dict(id='g11-past-simple-continuous', mod=7, sk=['GR_PAST'], sb='',
 en='Past simple and past continuous', ar='الماضي البسيط والماضي المستمر',
 table=[('Past simple', "V2 (played, saw) · didn't + V1 · Did … + V1?", 'finished action at a known time'),
        ('Past continuous', 'was / were + V-ing', 'in progress at a past moment'),
        ('when + past simple, past continuous', 'When the phone rang, Ali was watching TV.', 'short action interrupts'),
        ('when + past simple, past simple', 'When the phone rang, Ali answered it.', 'one after the other'),
        ('while / as + past continuous, past simple', 'While Ali was watching TV, the phone rang.', ''),
        ('while + continuous, continuous', 'While I was reading, my brother was painting.', 'two long actions'),
        ('Time clues', 'yesterday, ago, in 2010 → simple · at 8 pm yesterday, this time last week → continuous', '')],
 rule='Use "when" usually with the short action and "while" with the long one. Two finished actions in order → both past simple.',
 rule_ar='when غالبًا مع الحدث القصير و while مع الطويل، وحدثان متتاليان ← كلاهما ماضٍ بسيط.',
 ex=['Neil Armstrong walked on the Moon in 1969.', 'They were waiting for the bus when it started to rain.', 'He broke his leg while he was skiing.'],
 mistake=('When the teacher came in, the students were standing up to greet him. (wrong meaning) ✗', 'When the teacher came in, the students stood up to greet him. ✓', 'وقف الطلاب بعد دخول المعلم: حدثان متتاليان.'),
 rem_ins='Choose the correct answer.',
 rem=[mcq('I ______ TV when the lights went out.', ['watch', 'watched', 'was watching', 'am watching'], 'was watching'),
      mcq('While she was cooking, the phone ______.', ['rings', 'has rung', 'rang', 'was ringing'], 'rang'),
      mcq('At 8 pm last night, we ______ dinner.', ['were having', 'have', 'are having', 'had'], 'were having'),
      mcq('We ______ to Turkey two years ago.', ['have travelled', 'travel', 'travelled', 'were travelling'], 'travelled'),
      mcq('______ you see the match yesterday?', ['Were', 'Was', 'Do', 'Did'], 'Did'),
      mcq('While I was reading, my brother ______ the guitar.', ['played', 'was playing', 'plays', 'has played'], 'was playing'),
      mcq('He ______ his leg while he was skiing.', ['was breaking', 'breaks', 'has broken', 'broke'], 'broke'),
      mcq('She ______ her homework last night.', ["didn't finish", "wasn't finish", "hasn't finished", "doesn't finish"], "didn't finish")],
 enr_ins='Rewrite the sentences using the word(s) in brackets.',
 enr_box='',
 enr=[gap('While we were boarding the plane, it started raining. (when)', 'We were boarding the plane when it started raining.'),
      gap('They were having a picnic when it started raining. (While)', 'While they were having a picnic, it started raining.'),
      gap('I was walking home. I saw an accident. (when)', 'I was walking home when I saw an accident.'),
      gap('He fell asleep during the film. (While … was watching)', 'While he was watching the film, he fell asleep.'),
      gap('My father was reading. My mother was cooking. (While)', 'While my father was reading, my mother was cooking.'),
      gap('Write three sentences about yesterday evening using when and while.', 'Open answer')]),

dict(id='g11-used-to-would', mod=7, sk=['GR_USED', 'GR_FUT'], sb='',
 en='used to · would · be / get used to · was going to', ar='used to و would و be/get used to و was going to',
 table=[('used to + V1', 'past habits and states, no longer true', 'I used to live in Al Khor.'), ('would + V1', 'repeated past actions (NOT states)', 'Every summer we would go to the beach.'),
        ('be used to + noun / V-ing', 'accustomed now', "I'm used to waking up early."), ('get used to + noun / V-ing', 'becoming accustomed', "You'll soon get used to the heat."),
        ('was / were going to + V1', 'a past plan that did not happen', 'I was going to call you, but I forgot.')],
 rule='used to + V1 (past) ≠ be used to + V-ing (accustomed now). would cannot be used with states like have, live, like, be.',
 rule_ar='used to + المصدر للماضي، أما be used to + ing فمعناها معتاد الآن. ولا نستخدم would مع أفعال الحالة.',
 ex=['My grandfather used to have a big farm.', 'My grandmother would tell us a story every night.', 'We were going to visit Oman, but our flight was cancelled.'],
 mistake=('My grandfather would have a farm. ✗', 'My grandfather used to have a farm. ✓', 'have (يملك) حالة: لا نستخدم would.'),
 rem_ins='Choose the correct answer.',
 rem=[mcq('When I was a child, I ______ play in the street every evening.', ['get used to', 'use to', 'used to', 'am used to'], 'used to'),
      mcq('I ______ waking up early now. It\'s easy for me.', ['used to', 'am used to', 'use to', 'would'], 'am used to'),
      mcq('It will take time to ______ the hot weather.', ['would', 'used to', 'get used to', 'use to'], 'get used to'),
      mcq('______ you use to walk to school?', ['Do', 'Would', 'Did', 'Were'], 'Did'),
      mcq('She didn\'t ______ like vegetables, but now she loves them.', ['use to', 'using to', 'uses to', 'used to'], 'use to'),
      mcq('I ______ call you, but I forgot.', ['would', 'was going to', 'used to', 'am used to'], 'was going to'),
      mcq('He isn\'t used to ______ on the left.', ['drove', 'driven', 'drive', 'driving'], 'driving'),
      mcq('They were going to ______ a new car, but they changed their minds.', ['buying', 'bought', 'buys', 'buy'], 'buy')],
 enr_ins='Rewrite the sentences using the word(s) in brackets.',
 enr_box='',
 enr=[gap('In the past, I played football every day, but I don\'t now. (used to)', 'I used to play football every day.'),
      gap('Living in a big city is normal for me now. (used to)', "I'm used to living in a big city."),
      gap('My grandmother told us a story every night. (would)', 'My grandmother would tell us a story every night.'),
      gap('I planned to study, but I fell asleep. (was going to)', 'I was going to study, but I fell asleep.'),
      gap('Did you have long hair when you were young? (use to)', 'Did you use to have long hair when you were young?'),
      gap('Write three sentences comparing your childhood and now using used to, would and be used to.', 'Open answer')]),

